cd multicode/obelisk/full; python3 - <<'E'
p='core/challengeplay.mjs'
s=open(p).read()
new='''  const oreTable = eventsData.tables.ores;
  const oCol = oreTable ? oreTable.columns : [];
  const oIdCol = oCol.indexOf('id');
  const oOreCol = oCol.indexOf('ore');
  const oZoneCol = oCol.indexOf('zone');
  const oModeCol = oCol.indexOf('mode');
  const oreRows = oreTable ? oreTable.rows : [];

  // правило 10: добыча руды камнем; n — добавленное количество, зона — зона текущего этажа
  function oreEvents(ore, amount, zone) {
    const out = [];
    for (const row of oreRows) {
      if (row[oOreCol] !== ore) continue;
      if (row[oZoneCol] !== null && row[oZoneCol] !== zone) continue;
      out.push({ id: row[oIdCol], mode: row[oModeCol], n: amount });
    }
    return out;
  }

  const starTable = eventsData.tables.superStars;
  const sCol = starTable ? starTable.columns : [];
  const sIdCol = sCol.indexOf('id');
  const sTriggerCol = sCol.indexOf('trigger');
  const sModeCol = sCol.indexOf('mode');
  const sNCol = sCol.indexOf('n');
  const starRows = starTable ? starTable.rows : [];

  // правило 11: суперзвезда поймана автоловлей
  function superStarEvents(trigger) {
    const out = [];
    for (const row of starRows) {
      if (row[sTriggerCol] !== trigger) continue;
      out.push({ id: row[sIdCol], mode: row[sModeCol], n: row[sNCol] });
    }
    return out;
  }

  return { fire, pause, isChainTick, chainTickEvents, autobombEvents, floorDownEvents, contractEvents, prestigeEvents, oreEvents, superStarEvents };'''
old="  return { fire, pause, isChainTick, chainTickEvents, autobombEvents, floorDownEvents, contractEvents, prestigeEvents };"
assert old in s
open(p,'w').write(s.replace(old,new))
